import {exploreService} from '../../services/exploreService';
import type {ExploreFilters,ExploreKind,ExplorePage} from '../../types/explore';
// Only rank/search backend records. IDs, prices, ratings and availability are
// never generated by the model. An empty strong match falls back to real records.
export async function loadAdvisorMatches(kind:ExploreKind,filters:ExploreFilters,keywords:string[],signal?:AbortSignal):Promise<ExplorePage&{weak:boolean;matchFilters:ExploreFilters;matchQuery:string}>{
 const query=(filters.advisorStyleKey||filters.styleId)? '':keywords[0]||'';
 const page=await exploreService.search(kind,filters,query,undefined,signal);
 if(page.items.length||(!filters.styleId&&!filters.advisorStyleKey&&!query))return {...page,weak:!filters.styleId&&!filters.advisorStyleKey,matchFilters:filters,matchQuery:query};
 if(signal?.aborted)throw new Error('Cancelled');
 const broad=await exploreService.search(kind,{...filters,styleId:undefined,advisorStyleKey:undefined},'',undefined,signal);
 return {...broad,weak:true,matchFilters:{...filters,styleId:undefined,advisorStyleKey:undefined},matchQuery:''};
}
